(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.03+my*0.01+t*0.5)*8 + Math.cos(my*0.025-t*0.4)*6;
  const w2y = Math.cos(mx*0.01-my*0.03-t*0.45)*8 + Math.sin(mx*0.02+t*0.55)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.9],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1.1],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.8],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,1.2],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.7],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,1.0],
    [80+Math.sin(t*0.7+3)*70,40+Math.cos(t*0.6+4)*50,0.11,2.1,0.85],
    [400+Math.cos(t*0.45+2)*60,220+Math.sin(t*0.65+1)*40,0.13,1.8,1.15]
  ];
  let aS=0,iS=0,hS=0;
  for(const[sX,sY,f,sp,amp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*amp;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp;
    hS+=Math.sin(d*f*1.3-t*sp*0.8+2.5)*amp*0.5;
  }
  const act=aS/8,inh=iS/8,harm=hS/8;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=(Math.sin(sx*0.08+sy*0.05-t*1.3)+Math.cos(sx*0.06-sy*0.09+t*1.7))/2;
  const bg3=(Math.sin(sx*0.16+sy*0.1+t*2.5)+Math.sin(sx*0.12-sy*0.18-t*2.0))/2;
  const bg=bg1*0.5+bg2*0.3+bg3*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2=(Math.sin(dist*0.07+ang*2+t*0.8)+Math.cos(dist*0.06-ang*5+t*1.0))*0.25;
  const cross=Math.sin(act*inh*2+t*0.5)*0.3;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+sp1+sp2+harm*0.4+cross)*2.2);
  const c1=Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5;
  const c2=Math.sin(sx*0.08+1.5)*Math.cos(sy*0.1+0.8)+Math.sin((sx-sy)*0.07-t*0.7)*0.4;
  const cell=Math.tanh((c1*0.6+c2*0.4)*1.5)*0.3;
  const grain=Math.sin(sx*0.5+t*10)*Math.sin(sy*0.5+t*8)*0.04;
  const blend=reaction*0.65+cell*0.25+grain+harm*0.1;
  const v=blend*0.5+0.5;
  const pal=[[5,12,45],[12,45,85],[18,85,120],[25,140,135],[60,175,130],[180,200,80],[220,175,60],[215,120,70],[185,65,80],[130,35,70],[60,18,55],[5,12,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2+Math.abs(harm)*0.05;
  const edge=Math.abs(reaction)>0.65?1.0+(Math.abs(reaction)-0.65)*0.5:1.0;
  const cg=1.0+Math.max(0,1-dist/200)*0.15*Math.sin(t*0.3);
  const b=lum*edge*cg;
  return[Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*b)|0,Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*b)|0,Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*b)|0];
}
